### Options API vs Composition API
**Options API**：按选项组织（data/methods/computed/watch）
**Composition API**：按逻辑组织（setup/ref/reactive/computed/watch）

### 组合式函数（Composables）
将可复用逻辑提取为函数，以use开头命名。
```js
// useMouse.js
import { ref, onMounted, onUnmounted } from 'vue';
export function useMouse() {
    const x = ref(0);
    const y = ref(0);
    function update(e) { x.value = e.clientX; y.value = e.clientY; }
    onMounted(() => window.addEventListener('mousemove', update));
    onUnmounted(() => window.removeEventListener('mousemove', update));
    return { x, y };
}
```

理解时可以优先抓住「能说出Vue组件的生命周期顺序；能区分Options API和Composition API；能解释ref和reactive的区别」。这些点分别对应定义、执行流程和边界条件；要把触发条件、状态变化和结果影响串起来，而不是孤立背词

// Composition API 组件
import { ref, reactive, computed, watch, onMounted, onUnmounted } from 'vue';

export default {
  setup() {
    // 响应式数据
    const count = ref(0);
    const state = reactive({ name: 'Vue', items: [] });

    // 计算属性
    const double = computed(() => count.value * 2);

    // 侦听器
    watch(count, (newVal, oldVal) => {
      console.log(`${oldVal} -> ${newVal}`);
    });

    watchEffect(() => {
      // 自动收集依赖
      document.title = `Count: ${count.value}`;
    });

    // 生命周期
    onMounted(() => {
      console.log('mounted');
    });

    onUnmounted(() => {
      console.log('unmounted');
    });

    // 方法
    function increment() {
      count.value++;
    }

    return { count, double, state, increment };
  }
};

// 组合式函数：useFetch
import { ref, watchEffect } from 'vue';

export function useFetch(url) {
  const data = ref(null);
  const error = ref(null);
  const loading = ref(true);

  async function fetchData() {
    loading.value = true;
    try {
      const res = await fetch(url.value || url);
      data.value = await res.json();
    } catch (e) {
      error.value = e;
    } finally {
      loading.value = false;
    }
  }

  if (typeof url === 'object' && url.value !== undefined) {
    watchEffect(fetchData); // 响应式URL
  } else {
    fetchData();
  }

  return { data, error, loading, refetch: fetchData };
}

// 使用组合式函数
import { useFetch } from './useFetch';

export default {
  setup() {
    const { data: users, loading } = useFetch('/api/users');
    return { users, loading };
  }
};

// <script setup> 语法糖
<script setup>
import { ref, computed } from 'vue';
import { useFetch } from './useFetch';

const count = ref(0);
const double = computed(() => count.value * 2);
const { data: users } = useFetch('/api/users');
</script>
